# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: digest
def digest(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: fold
def fold(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return fold(shape(digest(intake(sift(raw)))))

